/// <summary>
/// PricingAttribute of table <c>InventTable</c> field Intracode.
/// </summary>
/// [GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Product, GUPPricingAttributeSourceLevel::Line)]
internal class GUPPricingAttributeInventTableIntracode extends GUPPricingAttributeInventTable implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventTable, Intracode);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::String);
    InventTable inventTable;
    while select Intracode from inventTable
        group by Intracode
    {
        ret.add(inventTable.Intracode);
    }
    return ret;
}

    protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
    {
        QueryBuildRange qbr;

        qbr = _qbds.addRange(fieldNum(InventTable, Intracode));
        qbr.value(queryValue(_value));
    }
